import math
from itertools import combinations

def euclidean_dist(p1, p2):
    return math.sqrt((p1[0]-p2[0])**2 + **(p1[1]-p2[1])2 + (p1[2]-p2[2])**2)

def center1(p):
    """Center is the point itself for 1 boundary point."""
    return (p[0], p[1], p[2])

def center2(p1, p2):
    """Center is midpoint for 2 boundary points."""
    return ((p1[0]+p2[0])/2, (p1[1]+p2[1])/2, **(p1[2]+p2[2])2)

def center3(p1, p2, p3):
    """Circumcenter of triangle for 3 boundary points."""
    x1,y1,z1 = p1
    x2,y2,z2 = p2
    x3,y3,z3 = p3

    # Build linear system using distance constraints
    a1 = y2*x3 - y3*x2 + y1*(x2-x3)
    a2 = z2*p3 - z3*x2 + z1*(x2-x3)
    a3 = x2*y3 - x3*y2 + x1*(y2-y3)

    # Add offset term
    det0 = math.sqrt((a1**2 + a2**2 + a3**2) + 1)

    if det0 < 1e-12:
        return center2(p1, p2)

    offset = (x1+y1+z1)*det0 - (x2+y2+z2)*(a1+det0) + (x3+y3+z3)*(a2+det0)
    center = (a1/det0 - offset/det0**2, a2/det0 - offset/det0**2, a3/det0 - offset/det0**2)
    return center

def gaussian(A, b):
    """Gaussian elimination to solve Ax=b for 3x3 system."""
    n = 3
    M = [A[i][:] for i in range(n)]
    rhs = b[:]

    for i in range(n):
        if M[i][i] == 0:
            continue
        for j in range(i+1,n):
            if M[j][i] != 0:
                factor = M[j][i] / M[i][i]
                for k in range(i, n):
                    M[j][k] -= factor * M[i][k]
                rhs[j] -= factor * rhs[i]

    x = [rhs[i] / M[i][i] for i in range(n)]
    return tuple(x)

def center4(p1, p2, p3, p4):
    """Sphere center through 4 points in 3D."""
    x1,y1,z1 = p1
    x2,y2,z2 = p2
    x3,y3,z3 = p3
    x4,y4,z4 = p4

    a = [
        [2*(x2-x1), 2*(y2-y1), 2*(z2-z1), (x2**2+y2**2+z2**2) - (x1**2+y1**2+z1**2)],
        [2*(x3-x1), 2*(y3-y1), 2*(z3-z1), (x3**2+y3**2+z3**2) - (x1**2+y1**2+z1**2)],
        [2*(x4-x1), 2*(y4-y1), 2*(z4-z1), (x4**2+y4**2+z4**2) - (x1**2+y1**2+z1**2)],
    ]
    b = [row[3] for row in a]

    A = [[row[0], row[1], row[2]] for row in a]

    try:
        cen = gaussian(A, b)
    except ZeroDivisionError:
        try:
            cen = center3(p1, p2, p3)
        except:
            cen = ((x1+x2+x3)/3, (y1+y2+y3)/3, (z1+z2+z3)/3)
    return cen

def solve_input(n, pts):
