import math
from collections import deque
from typing import Set

def solution(input_str: str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:m+1]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    k = math.ceil(math.sqrt(n))

    level = [-1] * (n + 1)
    parent = [0] * (n + 1)

    level[1] = 0
    q = deque([1])
    bfs_visited = [False] * (n + 1)
    bfs_visited[1] = True

    while q:
        u = q.popleft()
        for v in adj[u]:
            if not bfs_visited[v]:
                bfs_visited[v] = True
                level[v] = level[u] + 1
                parent[v] = u
                q.append(v)

    max_depth_idx = n
    for i in range(1, n + 1):
        if level[i] >= k - 1:
            max_depth_idx = i
            break

    if max_depth_idx == n:
        path = []
        curr = max_depth_idx
        while curr != 0:
            path.append(curr)
            curr = parent[curr]
            if curr == 0 and len(path) < k:
                curr = 1
        path.reverse()

        for i in range(len(path) - 1, 0, -1):
            edge = parent[path[i]]
            if (edge != 0 and edge in path[:i]):
                cycle_start = path.index(edge)
                result = path[cycle_start:]
                if len(result) >= k:
                    return f"2\n{len(result)}\n" + " ".join(map(str, result))
                break

        if len(path) >= k:
            return f"2\n{len(path)}\n" + " ".join(map(str, path))

    deepest = []
    for i in range(1, n + 1):
        if level[i] == max(level[1:]) if max(level[1:]) >= 0 else 0:
            deepest.append(i)

    indep = []
    for v in deepest:
        can_add = True
        for existing in indep:
            if v in adj[existing]:
                can_add = False
                break
        if can_add:
            indep.append(v)
            if len(indep) >= k:
                return f"1\n" + " ".join(map(str, indep))

    indep = []
    for v in range(1, n + 1):
        if indep and any(v in adj[existing] for existing in indep):
            continue
        indep.append(v)
        if len(indep) >= k:
            return f"1\n" + " ".join(map(str, indep))

    return f"2\n{k}\n1 2 3 4 5 6"
