Looking at this problem, I need to understand the key insight: each cell in the grid has exactly one outgoing direction, forming a functional graph where every node eventually reaches a cycle. When robots move infinitely following directions, robots starting at different positions might collide if they're at the same cell at the same time step.

**Key Insight:** The structure of this functional graph consists of components, where each component is defined by its eventual cycle. Two cells can have robots placed in them without collision if and only if they eventually reach different cycles. Therefore:
1. The maximum number of robots = number of unique eventual cycles (components)
2. For maximum black cells, we count black cells in each component and find the maximum

Let me implement the solution:

```python
import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        if idx >= len(lines):
            break

        n, m = map(int, lines[idx].split())
        idx += 1

        # Read grid colors
        grid = []
        for i in range(n):
            grid.append(lines[idx])
            idx += 1

        # Read directions
        dirs = []
        for i in range(n):
            dirs.append(lines[idx])
            idx += 1

        size = n * m
        next_pos = {}

        for i in range(n):
            for j in range(m):
                pos = i * m + j
                d = dirs[i][j]
                if d == 'U':
                    ni, nj = i - 1, j
                elif d == 'D':
                    ni, nj = i + 1, j
                elif d == 'L':
                    ni, nj = i, j - 1
                else:  # 'R'
                    ni, nj = i, j + 1
                next_pos[pos] = ni * m + nj

        # DFS to find components based on cycle structure
        comp = {}
        comp_id = 0
        in_stack = {}
        path = []

        def dfs(pos):
            nonlocal comp_id
            if pos in comp:
                return comp[pos]

            in_stack[pos] = True
            path.append(pos)

            nxt = next_pos[pos]

            if nxt in in_stack:
                # Found cycle - all positions in cycle get new comp_id
                cycle_start_idx = path.index(nxt)
                for p in path[cycle_start_idx:]:
                    comp[p] = comp_id
                comp_id += 1
                # Continue processing remaining path
                for p in path[:cycle_start_idx]:
                    if comp[p] == -1 or p not in comp:
                        comp[p] = dfs(next_pos[path.index(p)])
            else:
                dfs(nxt)

            in_stack.pop(pos)
            path.pop()

        # Process all positions
        for i in range(n):
            for j in range(m):
                pos = i * m + j
                comp[pos] = dfs(pos)

        # Count black cells in each component and find max
        comp_black = {}
        for pos in range(size):
            i, j = divmod(pos, m)
            c = grid[i][j]
            cid = comp[pos]
            if cid not in comp_black:
                comp_black[cid] = {'0': 0, '1': 0}
            comp_black[cid][c] += 1

        max_black = max(v['0'] for v in comp_black.values())
        max_roots = comp_id if comp_id > 0 else sum(1 for _ in range(size))

        results.append(f"{max_roots} {max_black}")

    return '\n'.join(results)
