def validate_profile(mask, profile):
    n = len(mask)
    k = len(profile)

    if not profile:
        # Empty profile - all cells should be '_'
        return mask == '___' * n

    # Calculate minimum space needed: sum of groups + (k-1) separators
    total = sum(profile) + max(0, k - 1)

    if total > n:
        return False

    # Verify all '#' positions can be covered
    hash_positions = set(i for i, c in enumerate(mask) if c == '#')

    for start in range(n - k + 1):
        can_fit = True
        for pos in hash_positions:
            if not (start <= pos < start + k):
                can_fit = False
                break
        if can_fit:
            return True

    return False
